const research = $json.research || $json;
const meetingNumber = $json.meetingNumber || 1;
const date = $json.date || new Date().toISOString();
const durationMinutes = $json.durationMinutes || 45;
const start = new Date(date);
const end = new Date(start.getTime() + durationMinutes * 60 * 1000);
const title = `Family Meeting #${meetingNumber} - ${research.topic}`;
const sourceCount = (research.sources || []).length;
const readingTimeMinutes = (research.sources || []).reduce((sum, source) => sum + (source.readingTimeMinutes || 0), 0);

return [{
  json: {
    meeting: {
      id: $json.meetingId || `familyos-meeting-${meetingNumber}`,
      number: meetingNumber,
      title,
      topic: research.topic,
      category: research.category,
      date: start.toISOString(),
      childAgeLabel: $json.childAgeLabel || $json.familyContext?.child?.ageLabel || '',
      status: 'Ready',
      preparationStatus: 'Ready',
      calendarEventId: $json.calendarEventId || null,
      topicPageId: $json.topicPageId || null,
      readingTimeMinutes,
      sourceCount
    },
    notion: {
      properties: {
        Title: title,
        MeetingNumber: meetingNumber,
        Date: start.toISOString(),
        Category: research.category,
        Topic: research.topic,
        Status: 'Ready',
        ChildAge: $json.childAgeLabel || $json.familyContext?.child?.ageLabel || '',
        PreparationStatus: 'Ready',
        ReadingTimeMinutes: readingTimeMinutes,
        SourceCount: sourceCount
      },
      blocks: [
        { type: 'heading_2', text: 'Pourquoi ce sujet maintenant ?' },
        { type: 'paragraph', text: research.whyNow || '' },
        { type: 'heading_2', text: 'Résumé' },
        { type: 'paragraph', text: research.executiveSummary || '' },
        { type: 'heading_2', text: 'À lire' },
        ...((research.sources || []).map(source => ({ type: 'bulleted_list_item', text: `${source.title} - ${source.url}` })))
      ]
    },
    calendar: {
      summary: title,
      description: `Sujet : ${research.topic}\nCatégorie : ${research.category}\nTemps de lecture : ${readingTimeMinutes} minutes`,
      start: start.toISOString(),
      end: end.toISOString()
    },
    telegramConfirmation: {
      text: `Meeting prêt\nSujet : ${research.topic}\nDate : ${start.toISOString()}\nTemps de lecture : ${readingTimeMinutes} minutes`,
      notionUrl: null
    }
  }
}];
